// ============================================================
//  送出服務呼叫
//  輸入：msg.payload = 服務要帶的參數（物件），例如 {altitude: 1.5}
//        沒有參數的服務（std_srvs/Trigger）可以不填
//  輸出 1 → websocket out（送給 rosbridge）
//  輸出 2 → 積木的輸出（立刻失敗、或逾時的時候）
// ============================================================
const service = env.get("SERVICE");
const url = env.get("ROSBRIDGE_URL");

function failNow(message) {
    msg.payload = { success: false, message };
    msg.ros = { service, timedOut: false };
    return [null, msg];
}

if (!service) return failNow("積木沒有設定服務名稱（SERVICE）");
// 沒連上時 websocket out 送出會直接被丟掉（只印一行警告），
// 使用者會以為指令送出了。所以先擋下來，立刻告訴他原因。
if (!flow.get("connected")) return failNow(`還沒連上 rosbridge（${url}）`);

// 每次呼叫一個不重複的 id，回覆時用它對回「是哪一次呼叫」。
// 雖然每個積木有自己的連線、不會收到別人的回覆，但同一個積木
// 可能連按兩次，還是要分得出來。
const id = `call_${Date.now()}_${Math.floor(Math.random() * 1e6)}`;
const args = (msg.payload && typeof msg.payload === "object" && !Array.isArray(msg.payload))
    ? msg.payload : {};

// 把原本的 msg 存起來，回覆時沿用（使用者在 msg 上加的欄位不會不見）。
// flow context 在 subflow 裡是「這個積木自己的」，不會跟別的積木混在一起。
const pending = flow.get("pending") || {};
pending[id] = RED.util.cloneMessage(msg);
flow.set("pending", pending);

const timeoutS = Number(env.get("TIMEOUT")) > 0 ? Number(env.get("TIMEOUT")) : 10;
setTimeout(() => {
    const p = flow.get("pending") || {};
    if (!p[id]) return;                 // 已經收到回覆了
    const orig = p[id];
    delete p[id];
    flow.set("pending", p);
    orig.payload = { success: false, message: `${timeoutS} 秒內沒有回應` };
    orig.ros = { service, id, timedOut: true };
    node.send([null, orig]);
}, timeoutS * 1000);

// rosbridge 協定的 call_service：op / id / service / args
return [{ payload: JSON.stringify({ op: "call_service", id, service, args }) }, null];

// ============================================================
//  收到 rosbridge 的訊息，挑出服務回覆
// ============================================================
let m;
try {
    // 收到的可能是 Buffer（ws 函式庫的行為），先轉成字串
    m = JSON.parse(Buffer.isBuffer(msg.payload) ? msg.payload.toString() : msg.payload);
} catch (e) {
    return null;
}
if (m.op !== "service_response") return null;

const p = flow.get("pending") || {};
const orig = p[m.id];
if (!orig) return null;                 // 不是這個積木送的，或已經逾時
delete p[m.id];
flow.set("pending", p);

if (m.result) {
    // 服務正常回覆：values 就是服務的回傳內容，例如 { success, message }
    orig.payload = m.values;
} else {
    // rosbridge 本身呼叫失敗（服務不存在、格式不對…），values 是錯誤訊息
    const detail = typeof m.values === "string" ? m.values : JSON.stringify(m.values);
    orig.payload = { success: false, message: `rosbridge 呼叫失敗：${detail}` };
}
orig.ros = { service: env.get("SERVICE"), id: m.id, result: m.result, timedOut: false };
return orig;

// ============================================================
//  追蹤連線狀態（websocket in 連上／斷線時會發出狀態事件）
//  顯示在積木下方，並記下目前有沒有連上
// ============================================================
const ev = msg.status && msg.status.event;
if (ev === "connect") {
    flow.set("connected", true);
    return { payload: { fill: "green", shape: "dot", text: "已連線" } };
}
if (ev === "disconnect" || ev === "error") {
    flow.set("connected", false);
    // 斷線後 Node-RED 每 3 秒會自動重連（22-websocket.js），這裡不用處理
    return { payload: { fill: "red", shape: "ring", text: "未連線（自動重連中）" } };
}
return null;

// ============================================================
//  收到 rosbridge 的訊息，只留這個 topic 的資料
// ============================================================
let m;
try {
    m = JSON.parse(Buffer.isBuffer(msg.payload) ? msg.payload.toString() : msg.payload);
} catch (e) {
    return null;
}
if (m.op !== "publish" || m.topic !== env.get("TOPIC")) return null;
// payload 就是 ROS 訊息本身，例如 std_msgs/String 會是 { data: "..." }
return { topic: m.topic, payload: m.msg };

// ============================================================
//  連上時送出訂閱；斷線時更新狀態
//  輸出 1 → websocket out（subscribe 請求）
//  輸出 2 → 積木下方的狀態
// ============================================================
const ev = msg.status && msg.status.event;
const topic = env.get("TOPIC");

if (ev === "connect") {
    if (!topic) {
        return [null, { payload: { fill: "red", shape: "ring", text: "沒有設定 TOPIC" } }];
    }
    // ⚠️ 每次（重新）連上都要再訂閱一次。
    //    rosbridge 不會記得之前誰訂閱過什麼，重開之後訂閱就消失了。
    const req = { op: "subscribe", id: `sub_${topic}`, topic };
    const type = env.get("TYPE");
    if (type) req.type = type;
    const throttle = Number(env.get("THROTTLE_MS"));
    if (throttle > 0) req.throttle_rate = throttle;   // rosbridge 端限制最快多久送一筆
    return [
        { payload: JSON.stringify(req) },
        { payload: { fill: "green", shape: "dot", text: `已訂閱 ${topic}` } },
    ];
}
if (ev === "disconnect" || ev === "error") {
    return [null, { payload: { fill: "red", shape: "ring", text: "未連線（自動重連中）" } }];
}
return null;

// 把 drone_api_node 的狀態 JSON 整理成好讀的樣子
let s;
try {
    s = JSON.parse(msg.payload.data);   // std_msgs/String 的內容在 data 欄位
} catch (e) {
    return null;
}
if (!s.connected) {
    msg.payload = { 連線: false, 說明: "drone_api_node 沒收到 PX4 的狀態" };
    msg.key = "未連線";
    return msg;
}
// 寫進共用區：「等待完成」積木從這裡讀，就不用每個積木各開一條連線。
// 用 global 不用 flow —— flow context 是「每個分頁、每個 subflow 各一份」，
// 任務分頁和積木內部都讀不到控制分頁的 flow。
// 加上時間戳：等待積木只認「它開始等之後才發布的」那一筆，才不會讀到上一個動作的結果。
s._t = Date.now();
global.set("drone_status", s);

msg.payload = { 模式: s.mode, 解鎖: s.armed, 落地: s.landed, 高度_m: s.altitude_m };
// 看門狗觸發時要看得到，這是自動降落的唯一提示
if (s.watchdog && s.watchdog.tripped) {
    msg.payload.看門狗 = s.watchdog.reason;
}
if (s.task && s.task.state === "failed") {
    msg.payload.任務失敗 = `${s.task.name}：${s.task.message}`;
}
// 追蹤中顯示進度。三種狀態要分清楚：正在找／暫時看不到／正常追蹤 ——
// 車子靠近時會掉出相機視野，那時飛機還在追，不能顯示成「在找目標」。
//
// 2026-10-08 起用 track.phase（searching / following）而不是 track.searching ——
// 搜尋階段現在是「巡航一整條環線」，不是原地轉頭，所以要看得到走到第幾個航點
// 和第幾圈，否則使用者只看到「尋找目標中 90 秒」完全不知道有沒有在動。
//
// 2026-10-12：用詞和儀表板對齊（同一件事不要兩個名字），而且多兩件資訊：
//   ① 「跟丟了回頭找」和「冷啟動在找」分開 —— 前者代表車就在附近
//   ② 跟隨時顯示「實際距離 / 要保持的距離」和「保持了多久」，才看得出來穩了沒
const tr = s.track || {};
if (tr.active) {
    if (tr.phase === "searching") {
        const 頭 = tr.reacquire ? "跟丟了，回頭找" : "巡航找目標";
        if (tr.search_index !== null && tr.search_index !== undefined) {
            msg.payload.追蹤 = `${頭}：第 ${tr.search_index} 個航點` +
                               `（第 ${(tr.search_laps || 0) + 1} 圈，已找 ${tr.search_s} 秒）`;
        } else {
            msg.payload.追蹤 = `${頭}（已找 ${tr.search_s} 秒）`;
        }
    } else {
        const 想要 = (tr.want !== null && tr.want !== undefined) ? ` / ${tr.want}` : "";
        const 保持 = (tr.locked_s !== null && tr.locked_s !== undefined)
            ? `，保持 ${Math.round(tr.locked_s)} 秒` : "";
        msg.payload.追蹤 = `跟著目標 ${tr.distance}${想要} m${保持}` +
                           (tr.lost_s > 0.5 ? `（暫時看不到 ${tr.lost_s} 秒）` : "");
    }
}
// Nav2 導航（api/goto）。
// ⚠️ 進度要以 state 為準，**不要只看 distance_remaining** ——
//    目標不可達時 Nav2 的 feedback 會把 distance_remaining 退化成 0
//    （L2 實測：規劃不出路徑的目標先顯示 remain 0.0，再跳 failed）。
//    只看那個數字的話畫面會先顯示「已到達」然後突然失敗。
const nv = s.nav || {};
if (nv.state === "running") {
    const g = nv.goal || [];
    msg.payload.導航 = `往 (${g[0]}, ${g[1]})` +
        (nv.distance_remaining !== null && nv.distance_remaining !== undefined
            ? `，剩 ${nv.distance_remaining} m` : "");
} else if (nv.state === "failed") {
    msg.payload.導航失敗 = nv.message || "Nav2 回報失敗";
}
// 巡航中才多顯示進度（第幾個點／共幾個點）
const pt = s.patrol || {};
if (pt.active) {
    msg.payload.巡航 = `${pt.index}/${pt.total} 點`;
}
// 下一個 filter 節點「只比對 msg.key」：模式、解鎖、落地有變才輸出。
// 高度不放進 key —— 它每 0.5 秒都在變，放進去的話 debug 側欄會被洗版。
// 巡航進度也放進 key：飛到下一個點時要看得到，不然中間十幾秒完全沒訊息
// 2026-10-08：加 track.phase / search_index 和 nav.state —— 階段或航點變了
// 要輸出一筆，否則搜尋繞一整圈（40 秒以上）畫面上完全沒動靜。
// distance_remaining 刻意**不**放進 key：它每 0.5 秒都在變，會洗版。
msg.key = `${s.mode}|${s.armed}|${s.landed}|${(s.patrol || {}).index}` +
          `|${(s.task || {}).seq}|${(s.task || {}).state}|${(s.watchdog || {}).tripped}` +
          `|${(s.track || {}).active}|${(s.track || {}).distance}` +
          `|${(s.track || {}).phase}|${(s.track || {}).search_index}` +
          `|${(s.nav || {}).state}`;
return msg;

// 只留 drone_api_node 的 log，格式簡化成「[等級] 內容」
// /rosout 會收到「所有」節點的 log（rosbridge 自己也一直在印），所以要過濾。
// 多機時把 MAV1 改成對應的 namespace。
const NAME = "MAV1.drone_api_node";
const log = msg.payload;                 // rcl_interfaces/msg/Log
if (!log || log.name !== NAME) return null;
const LEVEL = { 10: "DEBUG", 20: "INFO", 30: "WARN", 40: "ERROR", 50: "FATAL" };
msg.topic = log.name;
msg.payload = `[${LEVEL[log.level] || log.level}] ${log.msg}`;
return msg;

// 整理 systemctl / journalctl 的輸出，讓 Debug 側欄看得懂
// exec 節點的第 1 個輸出是 stdout、第 2 個是 stderr，兩個都接到這裡。
const raw = (msg.payload === undefined || msg.payload === null ? "" : msg.payload)
    .toString().trim();
if (!raw) return null;              // 指令成功但沒輸出的情況，不用顯示

// systemctl is-active 只會印一個字，翻譯成看得懂的句子
const STATE = {
    "active": "模擬正在跑",
    "inactive": "模擬沒在跑",
    "failed": "模擬啟動失敗 —— 按「看模擬 log」查原因",
    "activating": "模擬啟動中…",
    "deactivating": "模擬關閉中…",
};
msg.payload = STATE[raw] || raw;
return msg;

// 等 drone_api_node 回報「上一個動作做完了」
//
// 為什麼不是等服務回應就好：服務是「下單」不是「送達」。按下起飛，服務 0.05 秒就回
// 「已開始起飛」，但飛機要 20 秒才爬到。真正的完成寫在狀態的 task 欄位裡。
//
// 為什麼要看時間戳：狀態每 0.5 秒才發一次，剛進來時讀到的可能還是「上一個動作」的
// 結果（已完成），那會讓這個積木立刻放行。所以只認「開始等之後才發布」的那一筆。
// 服務當場就被拒絕（參數錯、飛機在地上…），不用等，直接走失敗
if (msg.payload && msg.payload.success === false) {
    node.status({ fill: "red", shape: "ring", text: "被拒絕" });
    return { payload: { 失敗: msg.payload.message || "服務呼叫被拒絕" } };
}

const t0 = Date.now();
const limit = Number(env.get("TIMEOUT") || 120) * 1000;
// 送指令前的任務編號。要等到「編號和它不一樣」才算是這次的任務 ——
// 否則指令沒送成功時，會讀到上一個已完成的任務就放行（2026-09-24 踩到）。
const before = msg._seq_before;
let seq = null;

const timer = setInterval(() => {
    const s = global.get("drone_status");
    if (!s || !s._t || s._t < t0) {                 // 還沒有新鮮的狀態
        if (Date.now() - t0 > limit) { stop(); fail("等不到狀態更新"); }
        return;
    }
    const task = s.task || {};
    if (seq === null) {
        if (task.seq === before) { return; }        // 還是上一個任務，繼續等
        seq = task.seq;                             // 鎖定這一次的任務
    }
    if (task.seq !== seq) {
        // 有人按了別的按鈕 —— 這不是「失敗」，是使用者接手了。
        // 什麼都不輸出，流程安靜停在這裡，不要自作主張去降落。
        stop();
        node.status({ fill: "grey", shape: "ring", text: "已被手動指令接手" });
        node.warn("任務已被手動指令接手，流程停止");
        return;
    }

    if (task.state === "done") {
        stop();
        msg.payload = { 完成: task.name, 說明: task.message };
        node.send([msg, null]);
    } else if (task.state === "failed") {
        stop();
        fail(`${task.name}：${task.message}`);
    } else if (Date.now() - t0 > limit) {
        stop();
        fail(`等待逾時（${limit / 1000} 秒）`);
    } else {
        node.status({ fill: "blue", shape: "dot", text: `等 ${task.name}…` });
    }
}, 200);

function stop() { clearInterval(timer); }
function fail(why) {
    node.status({ fill: "red", shape: "ring", text: why });
    msg.payload = { 失敗: why };
    node.send([null, msg]);      // 第二個出口＝失敗，接你想要的處置
}

