const incoming = (msg.payload && typeof msg.payload === 'object')
    ? msg.payload : {};
// 欄位值來自積木的設定（雙擊積木就能改）
msg.payload = { altitude: Number(env.get("ALTITUDE")) };
// 傳進來的值可以覆蓋，但**只限這個動作本來就有的欄位**。
// 不能整包 assign —— 上一個積木送來的是 {完成:…,說明:…}，
// 整包塞進去會變成服務不認得的欄位，呼叫直接失敗（2026-09-24 踩到）。
for (const k of Object.keys(msg.payload)) {
    if (k in incoming) { msg.payload[k] = incoming[k]; }
}
// 記下「送指令前」的任務編號，等待時才分得出新舊任務
msg._seq_before = ((global.get("drone_status") || {}).task || {}).seq;
return msg;

